import cProfile
import pstats

PRODUCTS = [(f"SKU{i:04}", i * 10) for i in range(1_000)]
ORDERS = [f"SKU{i * 7 % 1_000:04}" for i in range(1_000)]

def find_price(sku):
    for code, price in PRODUCTS:            # linear search: O(n) per lookup
        if code == sku:
            return price

def format_line(sku, price):
    return f"{sku}: ₹{price:,}"

def build_report(orders):
    lines = [format_line(sku, find_price(sku)) for sku in orders]
    return len(lines)

profiler = cProfile.Profile()
print("lines:", profiler.runcall(build_report, ORDERS))

stats = pstats.Stats(profiler)
rows = [(ct, nc, name) for (_, _, name), (_, nc, _, ct, _) in stats.stats.items()]
for ct, nc, name in sorted(rows, reverse=True)[:3]:
    print(f"{name[:24]:<24} calls={nc:<5} cumulative={ct * 1000:8.1f} ms")

from functools import lru_cache

