from functools import lru_cache

@lru_cache(maxsize=256)
def delivery_fee(items: tuple) -> int:
    weight = sum(kg for _, kg in items)
    return 40 + 15 * max(0, round(weight) - 2)

cart = (("rice", 5), ("dal", 1))
print(delivery_fee(cart))
print(delivery_fee(cart))
print(delivery_fee.cache_info())

CALLS = 0
RATES = {"USD": 83.2, "EUR": 90.5, "AED": 22.65}

def fetch_rate(currency: str) -> float:
    """Pretend this is a slow API call (about 300 ms)."""
    global CALLS
    CALLS += 1
    return RATES[currency]

def convert_all(payments: list[tuple[str, float]]) -> list[float]:
    """Convert (currency, amount) pairs to rupees, rounded to 2 places."""
    rates = {}
    result = []
    for currency, amount in payments:
        if currency not in rates:
            rates[currency] = fetch_rate(currency)
        result.append(round(amount * rates[currency], 2))
    return result

payments = [("USD", 10), ("EUR", 5), ("USD", 2.5), ("USD", 1), ("EUR", 20)]
print(convert_all(payments), "API calls:", CALLS)

