def common_customers(today: list[int], yesterday: list[int]) -> list[int]:
    """Customer IDs that ordered on both days, sorted, without duplicates."""
    return sorted(set(today) & set(yesterday))

print(common_customers([101, 205, 333, 101], [333, 101, 999]))

