class CountingList(list):
    scans = 0
    def __contains__(self, item):
        CountingList.scans += 1
        return super().__contains__(item)
    def index(self, *args):
        CountingList.scans += 1
        return super().index(*args)
    def count(self, item):
        CountingList.scans += 1
        return super().count(item)

today = CountingList(range(0, 3000, 3))
yesterday = CountingList(range(0, 3000, 2))
got = common_customers(today, yesterday)
assert got == list(range(0, 3000, 6)), "The IDs in both lists are the multiples of 6 below 3000, in order. Got " + str(got[:5]) + "..."
assert CountingList.scans == 0, "Your function searched a list " + str(CountingList.scans) + " times with `in`. Turn the lists into sets first: set lookups are O(1)."
assert common_customers([5, 5, 1], [1, 5, 9]) == [1, 5], "Remove duplicates and sort: [5, 5, 1] and [1, 5, 9] give [1, 5]."
assert common_customers([], [1, 2]) == [], "If nobody ordered today, the answer is []."
